from queueing import payload

def submit(owner, enqueue, batch_size=20):
    # Validate batch_size
    if not isinstance(batch_size, int):
        raise ValueError('batch_size must be an integer')
    if batch_size < 1 or batch_size > 100:
        raise ValueError('batch_size must be between 1 and 100')
    return enqueue(payload(owner, batch_size))

def execute(task, process):
    batch_size = task.get('batch_size', 20)
    return process(task["owner"], batch_size)

import api
import queueing
import worker

def test_default_batch_size():
    # test that submit works with default batch_size
    def dummy_enqueue(p):
        return p
    payload_dict = api.submit('owner1', dummy_enqueue)
    assert 'owner' in payload_dict
    assert payload_dict['owner'] == 'owner1'
    # payload should have batch_size 20
    assert payload_dict['batch_size'] == 20

def test_explicit_batch_size():
    def dummy_enqueue(p):
        return p
    payload_dict = api.submit('owner2', dummy_enqueue, batch_size=30)
    assert payload_dict['batch_size'] == 30

def test_batch_size_validation_low():
    def dummy_enqueue(p):
        return p
    try:
        api.submit('owner3', dummy_enqueue, batch_size=0)
        assert False, 'should raise ValueError'
    except ValueError as e:
        assert 'between 1 and 100' in str(e) or 'must be between' in str(e)

def test_batch_size_validation_high():
    def dummy_enqueue(p):
        return p
    try:
        api.submit('owner4', dummy_enqueue, batch_size=101)
        assert False, 'should raise ValueError'
    except ValueError as e:
        assert 'between 1 and 100' in str(e) or 'must be between' in str(e)

def test_batch_size_validation_non_int():
    def dummy_enqueue(p):
        return p
    try:
        api.submit('owner5', dummy_enqueue, batch_size='x')
        assert False, 'should raise ValueError'
    except ValueError as e:
        assert 'integer' in str(e).lower()

def test_legacy_payload_without_batch_size():
    # call queueing.payload directly without batch_size (legacy)
    p = queueing.payload('owner6')  # default batch_size=20
    assert 'owner' in p
    assert 'batch_size' in p
    assert p['batch_size'] == 20

def test_worker_execute_uses_batch_size():
    def dummy_process(owner, bs):
        return f'{owner}:{bs}'
    task = {'owner': 'owner7', 'batch_size': 50}
    result = worker.execute(task, dummy_process)
    assert result == 'owner7:50'

def test_worker_execute_fallback_to_20():
    # task without batch_size key
    task = {'owner': 'owner8'}
    result = worker.execute(task, lambda owner, bs: f'{owner}:{bs}')
    assert result == 'owner8:20'

if __name__ == '__main__':
    test_default_batch_size()
    test_explicit_batch_size()
    test_batch_size_validation_low()
    test_batch_size_validation_high()
    test_batch_size_validation_non_int()
    test_legacy_payload_without_batch_size()
    test_worker_execute_uses_batch_size()
    test_worker_execute_fallback_to_20()
    print('All tests passed')
